public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Y and N must be positive integers");
    }
    int count = 0;
    int year = Y;
    while (true) {
        boolean isLeap = (year % 4 == 0) && ((year % 100 != 0) || (year % 400 == 0));
        if (isLeap) {
            count++;
            if (count == N) {
                return year;
            }
        }
        year++;
    }
}

