public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    if (N == 0) {
        return 1; // No triangles, the plane is a single region
    }
    long regions = 3L * N * N - 3L * N + 2;
    if (regions > Integer.MAX_VALUE) {
        throw new IllegalArgumentException("Result exceeds int range");
    }
    return (int) regions;
}

