public static String convertDatesToWeekdays(String date) {
    try {
        java.time.format.DateTimeFormatter formatter = java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy", java.util.Locale.US);
        java.time.LocalDate localDate = java.time.LocalDate.parse(date, formatter);
        String month = localDate.getMonth().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.US);
        int day = localDate.getDayOfMonth();
        int year = localDate.getYear();
        String weekday = localDate.getDayOfWeek().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.US);
        return String.format("%s %d, %d is a %s", month, day, year, weekday);
    } catch (java.time.format.DateTimeParseException e) {
        throw new IllegalArgumentException("Invalid date format. Expected MM dd yyyy", e);
    }
}

