public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }
    // Remainder 0 must have even count
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 must have even count
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // For other remainders, freq[r] must equal freq[k - r]
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // already handled k even case
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

