public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        int u = e[0], v = e[1];
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] parent = new int[n];
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    java.util.ArrayList<Integer> order = new java.util.ArrayList<>();
    stack.push(0);
    parent[0] = -1;
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order.add(node);
        for (int child : graph[node]) {
            if (child == parent[node]) continue;
            parent[child] = node;
            stack.push(child);
        }
    }
    int[] time = new int[n];
    for (int i = order.size() - 1; i >= 0; i--) {
        int node = order.get(i);
        int nodeTime = 0;
        for (int child : graph[node]) {
            if (child == parent[node]) continue;
            if (time[child] > 0 || hasApple[child]) {
                nodeTime += time[child] + 2;
            }
        }
        time[node] = nodeTime;
    }
    return time[0];
}

