        for (int child : graph[node]) {
            if (child == parent[node]) continue;
            parent[child] = node;
            stack.push(child);
        }
    }
    int[] time = new int[n];
    for (int i = order.size() - 1; i >= 0; i--) {
        int node = order.get(i);
        int nodeTime = 0;
        for (int child : graph[node]) {
            if (child == parent[node]) continue;
            if (time[child] > 0 || hasApple[child]) {
                nodeTime += time[child] + 2;
            }
        }
        time[node] = nodeTime;
    }
    return time[0];
}

