public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return true;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int count = 0;
    int mask = total - 1;
    int val = 0;
    for (int i = 0; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[val]) {
                seen[val] = true;
                count++;
                if (count == total) return true;
            }
        }
    }
    return false;
}

