public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int insertions = 0;
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                insertions++; // insert a '(' before this ')'
            } else {
                balance--; // match with an existing '('
            }
        }
    }
    return insertions + balance; // add ')' for remaining unmatched '('
}

