public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be positive");
    }
    // Maximum number of Fibonacci numbers needed for int range is 45
    int[] fib = new int[45];
    fib[0] = 1;
    fib[1] = 1;
    int size = 2;
    while (true) {
        long nextLong = (long) fib[size - 1] + fib[size - 2];
        if (nextLong > k) {
            break;
        }
        fib[size++] = (int) nextLong;
    }
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }
    return count;
}

