public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    ArrayDeque<Long> queue = new ArrayDeque<>();
    // Start BFS from digits 0-9
    for (int i = 0; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long cur = queue.poll();
        if (cur > high) {
            continue;
        }
        if (cur >= low) {
            result.add((int) cur);
        }
        if (cur == 0) {
            // Only extend 0 to 1
            long next = cur * 10 + 1;
            if (next <= high) {
                queue.offer(next);
            }
            continue;
        }
        int lastDigit = (int) (cur % 10);
        // Append lastDigit - 1
        if (lastDigit > 0) {
            long next = cur * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        // Append lastDigit + 1
        if (lastDigit < 9) {
            long next = cur * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

