public static String addThousandSeparator(int n) {
    String s = Integer.toString(n);
    boolean negative = s.startsWith("-");
    if (negative) {
        s = s.substring(1);
    }
    int len = s.length();
    if (len <= 3) {
        return negative ? "-" + s : s;
    }
    StringBuilder sb = new StringBuilder();
    int firstGroup = len % 3;
    if (firstGroup == 0) {
        firstGroup = 3;
    }
    sb.append(s.substring(0, firstGroup));
    for (int i = firstGroup; i < len; i += 3) {
        sb.append('.');
        sb.append(s.substring(i, i + 3));
    }
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

