public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Sort to handle duplicates
    java.util.Arrays.sort(A);
    int max = 0;
    for (int v : A) if (v > max) max = v;
    int maxSum = max * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) isSquare[i * i] = true;
    long[][] dp = new long[1 << n][n];
    for (int i = 0; i < n; i++) dp[1 << i][i] = 1;
    for (int mask = 1; mask < (1 << n); mask++) {
        for (int last = 0; last < n; last++) {
            if ((mask & (1 << last)) == 0) continue;
            long cur = dp[mask][last];
            if (cur == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (!isSquare[A[last] + A[next]]) continue;
                // Skip duplicate values to avoid counting identical permutations
                if (next > 0 && A[next] == A[next - 1] && (mask & (1 << (next - 1))) == 0) continue;
                int nextMask = mask | (1 << next);
                dp[nextMask][next] += cur;
            }
        }
    }
    long ans = 0;
    int fullMask = (1 << n) - 1;
    for (int i = 0; i < n; i++) ans += dp[fullMask][i];
    return (int) ans;
}

