public static int findSmallestInteger(int n) {
    // Convert the integer to a character array of its digits
    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the largest index i such that digits[i] < digits[i + 1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such index exists, the digits are in non‑increasing order
    // and no larger permutation is possible
    if (i < 0) {
        return -1;
    }

    // Step 2: Find the largest index j > i such that digits[j] > digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Step 3: Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 4: Reverse the subarray from i + 1 to the end
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert the resulting digit array back to an integer
    try {
        long resultLong = Long.parseLong(new String(digits));
        if (resultLong > Integer.MAX_VALUE) {
            return -1;
        }
        return (int) resultLong;
    } catch (NumberFormatException e) {
        // Should not happen, but return -1 just in case
        return -1;
    }
}

